<?php $ym=$calendarMonth??date('Y-m'); $first=new DateTimeImmutable($ym.'-01'); $daysIn=(int)$first->format('t'); $startDow=(int)$first->format('N'); $prev=$first->modify('-1 month')->format('Y-m'); $next=$first->modify('+1 month')->format('Y-m'); $today=date('Y-m-d'); $byDay=[]; foreach($events as $e){$d=substr((string)$e['start_at'],0,10);$byDay[$d][]=$e;} $months=['01'=>'Leden','02'=>'Únor','03'=>'Březen','04'=>'Duben','05'=>'Květen','06'=>'Červen','07'=>'Červenec','08'=>'Srpen','09'=>'Září','10'=>'Říjen','11'=>'Listopad','12'=>'Prosinec']; ?>
<div class="page-head"><div><h1>Kalendář</h1><div class="sub">Přehled vašich událostí, schůzek a termínů na jednom místě.</div></div><div class="actions"><a class="btn" href="/calendar?month=<?=date('Y-m')?>">Dnes</a><a class="btn" href="/calendar?month=<?=$prev?>">‹</a><a class="btn" href="/calendar?month=<?=$next?>">›</a></div></div>
<div class="card calendar-card"><div class="calendar-title"><h2><?= $months[$first->format('m')] ?> <?= $first->format('Y') ?></h2><span class="sub"><?=count($events)?> událostí v tomto měsíci</span></div><div class="calendar-weekdays"><span>Po</span><span>Út</span><span>St</span><span>Čt</span><span>Pá</span><span>So</span><span>Ne</span></div><div class="calendar-grid"><?php for($i=1;$i<$startDow;$i++): ?><div class="calendar-day empty"></div><?php endfor; ?><?php for($day=1;$day<=$daysIn;$day++): $date=$first->format('Y-m-').str_pad((string)$day,2,'0',STR_PAD_LEFT); ?><div class="calendar-day <?= $date===$today?'today':'' ?>"><button type="button" class="calendar-date" data-date="<?=$date?>"><?=$day?></button><?php foreach(($byDay[$date]??[]) as $e): ?><a class="calendar-event" href="#calendar-form" title="<?=\App\Core\View::e($e['title'])?>" data-date="<?=$date?>"><?=\App\Core\View::e($e['title'])?></a><?php endforeach; ?></div><?php endfor; ?></div></div>
<div class="calendar-lower"><div class="card" id="calendar-form"><h3>Nová událost</h3><p class="sub">Kliknutím na datum v kalendáři předvyplníte den.</p><form class="form" method="post" action="/calendar/save"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Název</label><input id="calendarTitle" name="title" placeholder="Např. Schůzka s klientem" required></div><div class="row"><div class="field"><label>Začátek</label><input id="calendarStart" type="datetime-local" name="start_at" required></div><div class="field"><label>Konec</label><input id="calendarEnd" type="datetime-local" name="end_at"></div></div><div class="row"><div class="field"><label>Zákazník</label><select name="customer_id"><option value="">Bez zákazníka</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=\App\Core\View::e($c['company_name']?:trim(($c['first_name']??'').' '.($c['last_name']??'')))?></option><?php endforeach;?></select></div><div class="field"><label>Zakázka</label><select name="job_id"><option value="">Bez zakázky</option><?php foreach($jobs as $j):?><option value="<?=$j['id']?>"><?=\App\Core\View::e($j['name'])?></option><?php endforeach;?></select></div></div><div class="field"><label>Typ</label><select name="type"><option value="event">Událost</option><option value="meeting">Schůzka</option><option value="task">Úkol</option><option value="job">Zakázka</option></select></div><div class="field"><label>Poznámka</label><textarea name="note" placeholder="Poznámka k události"></textarea></div><button class="btn primary">Přidat do kalendáře</button></form></div><div class="card"><h3>Události v měsíci</h3><?php if(!$events): ?><p class="sub">V tomto měsíci zatím nejsou žádné události.</p><?php else: ?><?php foreach($events as $e): ?><div class="calendar-list-item"><div><b><?=\App\Core\View::e($e['title'])?></b><div class="sub"><?=\App\Core\View::e($e['start_at'])?><?php if(!empty($e['company_name'])): ?> · <?=\App\Core\View::e($e['company_name'])?><?php endif; ?></div></div><span class="badge"><?=\App\Core\View::e($e['type'])?></span></div><?php endforeach; ?><?php endif; ?></div></div>
<script>document.querySelectorAll('.calendar-date').forEach(btn=>btn.addEventListener('click',()=>{const d=btn.dataset.date;document.getElementById('calendarStart').value=d+'T09:00';document.getElementById('calendarEnd').value=d+'T10:00';document.getElementById('calendar-form').scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('calendarTitle').focus();}));</script>